        s = "".join(re.findall(r"[A-Za-z]", b))
        sel = "".join(s[p-1] for p in MASK31 if p - 1 < len(s))
        out(acc, sel)
        sel2 = "".join(s[p-1] for p in MASK30 if p - 1 < len(s))
        out(acc, sel2)
        comp = "".join(s[i] for i in range(min(91, len(s))) if (i + 1) not in hostset)
        out(acc, comp[:200])
        # repeat the 91-window along the whole string
        acc2 = []
        base = 0
        while base + 91 <= len(s):
            acc2.append("".join(s[base + p - 1] for p in MASK31))
            base += 91
        out(acc, "".join(acc2)[:200])
    # macro phrases themselves selected by host ranks
    for mask in (MASK31, MASK30):
        sel = [macro[(p - 1) % len(macro)] for p in mask]
        out(acc, "".join(sel)[:200])
        out(acc, " ".join(sel)[:200])
    # the k-th letter of the k-th macro phrase, and host-ranked letters inside each phrase
    out(acc, "".join(macro[k][k % len(macro[k])] for k in range(len(macro))))
    for p in MASK31[:12]:
        out(acc, "".join(m[(p - 1) % len(m)] for m in macro))
    return acc[:900]

